    pub(crate) fn init_pipe_pair() -> OsExtraData {
        match UnixStream::pair() {
            Ok((receiver, sender)) => OsExtraData { sender, receiver },
            Err(e) => {
                match e.kind() {
                    io::ErrorKind::NotFound => panic!("failed to create UnixStream"),
                    io::ErrorKind::PermissionDenied => panic!("failed to create UnixStream"),
                    io::ErrorKind::ConnectionRefused => panic!("failed to create UnixStream"),
                    io::ErrorKind::ConnectionReset => panic!("failed to create UnixStream"),
                    io::ErrorKind::ConnectionAborted => panic!("failed to create UnixStream"),
                    io::ErrorKind::NotConnected => panic!("failed to create UnixStream"),
                    io::ErrorKind::AddrInUse => panic!("failed to create UnixStream"),
                    io::ErrorKind::AddrNotAvailable => panic!("failed to create UnixStream"),
                    io::ErrorKind::BrokenPipe => panic!("failed to create UnixStream"),
